import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, CUSTOM_ELEMENTS_SCHEMA, Inject, Input } from '@angular/core';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatRadioModule } from '@angular/material/radio';
import { FormControl, FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { environment } from '../../../../../environments/environment';
import { IssueService } from '../../../../shared/services/issues/issue.service';
import { UserDetail } from '../../../../core/interfaces/login.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { CommonService } from '../../../../shared/services/common/common.service';
import { ExportService } from '../../../services/export/export.service';
import { exportFilewithannot, FileListResponce } from '../../../interfaces/export.interface';
import { DatepickerComponent } from "../../../../shared/components/datepicker/datepicker.component";
import { ContactService } from '../../../../shared/services/contact/contact.service';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';

@Component({
  selector: 'app-export-form',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, CommonModule, MatCheckboxModule, MatSelectModule, IconComponent, ButtonComponent, MatRadioModule,
    ReactiveFormsModule, MatFormFieldModule, DatepickerComponent, AvatarComponent, MatTooltipModule],
  templateUrl: './export-form.component.html',
  styleUrl: './export-form.component.scss',
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
})
export class ExportFormComponent {
  @Input() nCaseid: string;
  isAdvanced: boolean = false;
  frm: any;
  cCasename: string;
  nUserid: any;
  issueList: any[] = [];
  contactList: any[] = [];
  gropuIssueList: any = [];
  SelectedFact: any[] = [];
  SelectedQFact: any[] = [];
  SelectedContact: any[] = [];
  SelectedQContact: any[] = [];
  SelectedQ: any[] = [];

  icons: any[] = [
    { name: 'Small', icon: 'textF', type: 'S', toolTip: 'Highlighter' },
    { name: 'Normal', icon: 'textF', type: 'N', toolTip: 'Freehand' },
    { name: 'Large', icon: 'textF', type: 'L', toolTip: 'Shape' },
  ]
  downloadPath: string = `${environment.cloudUrl}${environment.downloadpath}realtime-transcripts/exports/`;
  isLoading: boolean = false;
  cTranscript: string = 'N';
  userdetail: UserDetail;
  filelist: FileListResponce[] = [];
  jFiles: string;
  jFolders: string;
  isAllselected: boolean = false;
  isChecked: boolean = false;
  constructor(private commonService: CommonService, private issueService: IssueService, private contactService: ContactService, private store: SecureStorageService, private exportserice: ExportService,
    private cdr: ChangeDetectorRef, private tost: TostbarService,
    public dialogRef: MatDialogRef<ExportFormComponent>, @Inject(MAT_DIALOG_DATA) public data: any) {

    this.nCaseid = data.nCaseid;
    this.jFiles = data.jFiles;
    this.jFolders = data.jFolders;
  }

  async ngOnInit() {
    this.fetchIssues();
    this.fetchFiles();
    this.fetchContact();
    this.frm = new FormGroup({
      // nTaskid: new FormControl(null),
      cTranscript: new FormControl(this.cTranscript),
      bPagination: new FormControl(false),
      cPdftype: new FormControl('S'),

      bFact: new FormControl(true),
      cFsize: new FormControl('S'),
      jFIssue: new FormControl([]),
      jFContact: new FormControl([]),

      bQfact: new FormControl(true),
      cQFsize: new FormControl('S'),
      jQFIssue: new FormControl([]),
      jQFContact: new FormControl([]),


      bDoc: new FormControl(true),
      cDsize: new FormControl('S'),

      bAdvanced: new FormControl(false),
      bCoverpg: new FormControl(true),
      cPages: new FormControl('A'),
      cPagerange: new FormControl(''),

      cOrientation: new FormControl('A'),
      bFitpg: new FormControl(true),
      cPgsize: new FormControl('A4'),
    });

    this.userdetail = await this.store.getUserInfo();
  }

  changeFont(type, key) {
    this.frm.controls[key].setValue(type);
    console.log(this.frm.value);
  }

  async fetchFiles() {
    const res = await this.exportserice.getFilelist(this.jFiles, this.jFolders);
    this.filelist = res;
    this.filelist.map((item) => item.checked = true);
    this.isAllselected = true;
    this.cdr.detectChanges();
  }

  selectAll() {
    this.isAllselected = !this.isAllselected;
    this.filelist.forEach((item) => item.checked = this.isAllselected);
    this.cdr.detectChanges();
  }

  selectFile(item) {
    item.checked = !item.checked;
    this.isAllselected = this.filelist.every((item) => item.checked);
  }

  async fetchIssues() {
    this.issueList = [];
    this.issueList = await this.issueService.fetchIssueList(this.nCaseid);
    console.log('issueList', this.issueList);
    const groupedIssueList = Object.values(this.issueList.reduce((acc, item) => {
      const { nICid, cCategory } = item;
      if (!acc[nICid]) {
        acc[nICid] = {
          nICid,
          cCategory,
          sublist: []
        };
      }
      acc[nICid].sublist.push(item);
      return acc;
    }, {}));
    // this.issueList = groupedIssueList;
    this.gropuIssueList = groupedIssueList
    // console.log('grouped issue', this.issueList);
    this.cdr.detectChanges();
  }



  async fetchContact() {
    this.contactList = [];
    this.contactList = await this.contactService.getContactList(this.nCaseid);
    console.log('issueList', this.contactList);

    // console.log('grouped issue', this.issueList);
    this.cdr.detectChanges();
  }
  // changeIssue(id, key) {
  //   this.frm.value[key] = [...this.frm.value[key], id];
  // }
  checkAll(key, listnm, key1) {

    this.frm.patchValue({ [key]: this[listnm].map((item) => item[key1]) });
    this.cdr.detectChanges();
  }

  async submit() {
    try {

    if (!this.filelist.length) return;

    const jFiles = this.filelist.filter((item) => item.checked);

    if (!jFiles.length) {
      this.tost.error('Please select pdf files for export');
      return;
    }
    const isAllPdf = this.isAllFilesPDF(jFiles);

    if (!isAllPdf) {
      this.tost.error('Please select only pdf files');
      return;
    }
    let mdl: exportFilewithannot = this.frm.value;
    mdl.nCaseid = this.nCaseid;
    mdl.jPages = [];
      // mdl.jQFIssue = mdl.jQFIssue ? mdl.jQFIssue.filter(a => a > 0).map(a => a) : [];
      // mdl.jFIssue = mdl.jFIssue ? mdl.jFIssue.filter(a => a > 0).map(a => a) : [];

      // mdl.jQFContact = mdl.jQFContact ? mdl.jQFContact.filter(a => a > 0).map(a => a) : [];
      // mdl.jFContact = mdl.jFContact ? mdl.jFContact.filter(a => a > 0).map(a => a) : [];

      mdl.jQFIssue = Array.isArray(mdl.jQFIssue)
        ? mdl.jQFIssue.filter((a: any) => typeof a === 'string' && a.trim().length > 0)
        : [];

      mdl.jFIssue = Array.isArray(mdl.jFIssue)
        ? mdl.jFIssue.filter((a: any) => typeof a === 'string' && a.trim().length > 0)
        : [];

      mdl.jQFContact = Array.isArray(mdl.jQFContact)
        ? mdl.jQFContact.filter((a: any) => typeof a === 'string' && a.trim().length > 0)
        : [];


      mdl.jFContact = Array.isArray(mdl.jFContact)
        ? mdl.jFContact.filter((a: any) => typeof a === 'string' && a.trim().length > 0)
        : [];

    if (mdl.cPages === 'R' && mdl.cPagerange) {
      mdl.jPages = this.parsePageRange(this.frm.value.cPagerange);
    }
    mdl.jFiles = jFiles.map((item) => item.nBundledetailid);
    delete mdl.cPagerange;
    delete mdl.cPages;
    delete mdl.bAdvanced;
    if (this.isLoading) return;

    this.isLoading = true;
    this.cdr.detectChanges();

    const res: any = await this.exportserice.exportFilewithannot(mdl);
    this.isLoading = false;
    this.cdr.detectChanges();
    if (res) {
      if (res.msg == 1) {
        // this.tost.openSnackBar('File exported successfully');
        // this.downloadURI(res.path, res.name);
        this.dialogRef.close(true);
      }
      // else {
      //   this.tost.error('Failed to export');
      // }
    }
    } catch (error) {

    }
  }


  changeIssue(list, key, key1, key2) {
    this[key] = this[list].filter((item) =>
      this.frm.value[key1].includes(item[key2])
    );
    this.cdr.detectChanges();
  }

  removels(x, key, key1, key2) {

    this[key] = this[key].filter((item) => item[key2] !== x[key2]);
    this.frm.patchValue({ [key1]: this[key].map((item) => item[key2]) });
  }



  parsePageRange(pageRange: string): number[] {
    let result = new Set<number>();
    let ranges = pageRange.split(',');

    ranges.forEach(range => {
      if (range.includes('-')) {
        let [start, end] = range.split('-').map(Number);
        if (!isNaN(start) && !isNaN(end)) {
          for (let i = start; i <= end; i++) {
            result.add(i);
          }
        }
      } else {
        let num = Number(range);
        if (!isNaN(num)) {
          result.add(num);
        }
      }
    });

    return Array.from(result).sort((a, b) => a - b);
  }




  downloadURI(uri, name) {
    const fileName = `${this.downloadPath}${uri}?id:${Math.random()}`; // The file name you want to download
    this.commonService.downloadFile(fileName).subscribe(
      (blob) => {
        this.dialogRef.close()
        const a = document.createElement('a');
        const objectUrl = URL.createObjectURL(blob);
        a.href = objectUrl;
        a.download = name;
        a.click();
        URL.revokeObjectURL(objectUrl);
      },
      (error) => {
        console.error('Download error:', error);
        this.tost.error('Failed to download');
      }
    );
  }



  isAllFilesPDF(fileList: FileListResponce[]) {
    return fileList.every((file: FileListResponce) => file.cFiletype?.toUpperCase() === 'PDF');
  }

}
